&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;c8bg0&quot; data-offset-key=&quot;96r8g-0-0&quot;&gt;
