&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;eqdfh-0-0&quot;&gt;&lt;span data-offset-key=&quot;eqdfh-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Track record of facilitating high-impact workshops that align client objectives with solutions &lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
